#!/usr/bin/env bash
# Rewrites the Scoop manifest (bucket/) and Homebrew formula (Formula/) to point at a release.
# Usage: .github/scripts/update-manifests.sh <version> <path to the release's SHA256SUMS.txt>
set -euo pipefail

if [[ $# -ne 2 ]]; then
  echo "Usage: $0 <version> <SHA256SUMS.txt>" >&2
  exit 2
fi

version="$1"
sums="$2"
root="$(cd "$(dirname "$0")/../.." && pwd)"
base="https://github.com/pzarek/heic2jpeg/releases/download/v$version"

sha256() {
  local file="heic2jpeg-$version-$1"
  local hash
  hash="$(awk -v f="$file" '$2 == f { print $1 }' "$sums")"
  if [[ -z "$hash" ]]; then
    echo "No checksum for $file in $sums" >&2
    return 1
  fi
  echo "$hash"
}

win_x64="$(sha256 win-x64.zip)"
win_arm64="$(sha256 win-arm64.zip)"
linux_x64="$(sha256 linux-x64.tar.gz)"
linux_arm64="$(sha256 linux-arm64.tar.gz)"
osx_arm64="$(sha256 osx-arm64.tar.gz)"

mkdir -p "$root/bucket" "$root/Formula"

cat > "$root/bucket/heic2jpeg.json" <<EOF
{
    "version": "$version",
    "description": "Converts a folder of HEIC/HEIF photos to JPEG in parallel, with progress bars.",
    "homepage": "https://github.com/pzarek/heic2jpeg",
    "license": "MIT",
    "architecture": {
        "64bit": {
            "url": "$base/heic2jpeg-$version-win-x64.zip",
            "hash": "$win_x64"
        },
        "arm64": {
            "url": "$base/heic2jpeg-$version-win-arm64.zip",
            "hash": "$win_arm64"
        }
    },
    "bin": "heic2jpeg.exe"
}
EOF

cat > "$root/Formula/heic2jpeg.rb" <<EOF
# Generated by .github/scripts/update-manifests.sh on each release. Do not edit by hand.
class Heic2jpeg < Formula
  desc "Convert a folder of HEIC/HEIF photos to JPEG in parallel"
  homepage "https://github.com/pzarek/heic2jpeg"
  version "$version"
  license "MIT"

  on_macos do
    # The bundled ImageMagick library ships no Intel Mac build.
    depends_on arch: :arm64

    url "$base/heic2jpeg-$version-osx-arm64.tar.gz"
    sha256 "$osx_arm64"
  end

  on_linux do
    on_intel do
      url "$base/heic2jpeg-$version-linux-x64.tar.gz"
      sha256 "$linux_x64"
    end

    on_arm do
      url "$base/heic2jpeg-$version-linux-arm64.tar.gz"
      sha256 "$linux_arm64"
    end
  end

  def install
    bin.install "heic2jpeg"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/heic2jpeg --version")
  end
end
EOF

echo "Updated bucket/heic2jpeg.json and Formula/heic2jpeg.rb to $version"
